SELECT r.report_id AS reportId, r.reported_user_id AS reportedUserId, target.name AS reportedUserName, target.email AS reportedUserEmail, r.report_user_id AS reportUserId, reporter.name AS reportUserName, r.target_type AS targetType, r.target_id AS targetId, r.category AS category, r.detail AS detail, r.created_at AS createdAt, r.status AS status, r.processed_by AS processedBy, r.processed_at AS processedAt, r.process_reason AS processReason, r.login_restriction_days AS loginRestrictionDays FROM report r LEFT JOIN member target ON target.user_id = r.reported_user_id LEFT JOIN member reporter ON reporter.user_id = r.report_user_id
AND r.status = #{status}
AND r.target_type = #{targetType}
AND ( r.reported_user_id LIKE CONCAT('%', #{keyword}, '%') OR target.name LIKE CONCAT('%', #{keyword}, '%') OR r.report_user_id LIKE CONCAT('%', #{keyword}, '%') OR reporter.name LIKE CONCAT('%', #{keyword}, '%') OR r.category LIKE CONCAT('%', #{keyword}, '%') OR r.detail LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY CASE WHEN r.status = 'PENDING' THEN 0 ELSE 1 END, r.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM report r LEFT JOIN member target ON target.user_id = r.reported_user_id LEFT JOIN member reporter ON reporter.user_id = r.report_user_id
AND r.status = #{status}
AND r.target_type = #{targetType}
AND ( r.reported_user_id LIKE CONCAT('%', #{keyword}, '%') OR target.name LIKE CONCAT('%', #{keyword}, '%') OR r.report_user_id LIKE CONCAT('%', #{keyword}, '%') OR reporter.name LIKE CONCAT('%', #{keyword}, '%') OR r.category LIKE CONCAT('%', #{keyword}, '%') OR r.detail LIKE CONCAT('%', #{keyword}, '%') )
